import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {resolve} from 'node:path';import {pathToFileURL} from 'node:url';import {mkdir,writeFile} from 'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');const evidence=resolve('../../outputs/verification-v34-v31-zone-parity-v1');await mkdir(evidence);
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const result={};for(const version of [31,34]){
  const page=await browser.newPage({viewport:{width:1200,height:860}});const name=version===31?'ばせぼーるlv31_TBD_vs_LAD_剛体バット描画版.html':'ばせぼーるlv34_TBD_vs_LAD_UI復元版.html';await page.goto(pathToFileURL(resolve('../../outputs/'+name)).href);await page.evaluate(()=>document.fonts.ready);
