  else await page.evaluate(()=>{const a=document.getElementById('auto-overhead');a.checked=false;a.dispatchEvent(new Event('change'));document.querySelector('[data-camera="batter"]').click();});
  result[version]=await page.evaluate(version=>{const s=version===31?window.matchPreview.inspect():window.liveMatchPlayback.inspect().rendered;return {camera:s.camera,eye:s.cameraEye,yaw:s.cameraYaw,pitch:s.cameraPitch,zoneCorners:s.zoneCorners,inside:s.zoneCorners.filter(p=>p&&p.x>=0&&p.x<=600&&p.y>=0&&p.y<=432).length};},version);
