  await page.locator('.broadcast').screenshot({path:resolve(evidence,'batter-v'+version+'.png')});await page.close();
 }
 assert.deepEqual(result[31].zoneCorners,result[34].zoneCorners);assert.deepEqual(result[31].zoneCorners,result.preparation.zoneCorners);assert.equal(result[31].inside,2);
 await writeFile(resolve(evidence,'zone-parity.json'),JSON.stringify({status:'PASS',...result},null,2)+'\n');console.log(JSON.stringify({status:'PASS',originalV31Inside:result[31].inside,restoredV34Inside:result[34].inside,preparationInside:result.preparation.inside,exactCorners:true,corners:result[31].zoneCorners,evidence},null,2));
